export type RandomSource=()=>number;
function hash(seed:number|string):number { let value=2166136261; for(const char of String(seed)){value^=char.charCodeAt(0);value=Math.imul(value,16777619)} return value>>>0 }
export function createSeededRandom(seed:number|string):RandomSource { let state=hash(seed); return ()=>{state+=0x6d2b79f5;let value=state;value=Math.imul(value^(value>>>15),value|1);value^=value+Math.imul(value^(value>>>7),value|61);return ((value^(value>>>14))>>>0)/4294967296} }
export function gaussian(random:RandomSource):number { return Math.sqrt(-2*Math.log(Math.max(random(),Number.EPSILON)))*Math.cos(Math.PI*2*random()) }
EOF
